/**
 * O que é GERADO dentro do pacote — o que difere de um workspace de deploy do repositório.
 *
 * O `firebase.json` do repositório não serve como está por duas razões: o `predeploy` dele compila o
 * kernel (que no pacote já vem compilado, e cujo `src/` não viaja), e o hosting dele aponta para
 * `dist`. Aqui o `predeploy` compila SÓ o que o escritório escreveu.
 */

export interface RepoFunctionsPackage {
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
  engines?: Record<string, string>;
}

export interface HostingConfig {
  ignore: string[];
  rewrites: unknown[];
  headers: unknown[];
}

export const packageFirebaseJson = (hosting: HostingConfig): string => JSON.stringify({
  firestore: {
    rules: 'firestore.rules',
    indexes: 'firestore.indexes.json',
  },
  storage: {
    rules: 'storage.rules',
  },
  functions: {
    source: 'functions',
    predeploy: ['npm --prefix "$RESOURCE_DIR" run build'],
  },
  hosting: {
    public: 'hosting',
    ignore: hosting.ignore,
    rewrites: hosting.rewrites,
    headers: hosting.headers,
  },
}, null, 2) + '\n';

/**
 * O nome do pacote de functions da instalação, e o subcaminho da superfície curada que a Cloud Function
 * do ESCRITÓRIO importa dele: `import { forInstalledExtension } from 'microteia-functions/office'`.
 *
 * O nome é parte do contrato de autoria a partir do momento em que alguém o escreve num import, e por
 * isso ele deixou de ser uma string solta aqui dentro.
 */
export const FUNCTIONS_PACKAGE_NAME = 'microteia-functions';
export const OFFICE_SUBPATH = 'office';
export const OFFICE_MODULE = `${FUNCTIONS_PACKAGE_NAME}/${OFFICE_SUBPATH}`;

/**
 * As dependências são copiadas INTACTAS do `functions/package.json` do repositório, para que o
 * `package-lock.json` que viaja junto continue válido. O que muda é só o entrypoint (passa a ser o
 * `index.js` que soma kernel e custom), o `build`, que agora compila apenas `custom/`, e o `exports`,
 * que abre a superfície curada para o `custom/` sem custar uma dependência.
 */
/**
 * A `version` não é enfeite: sem ela o npm não consegue formar `nome@versão` e todo aviso dele sobre
 * este pacote sai com `package: undefined`, o que faz parecer que o arquivo está corrompido.
 *
 * `engines.node` vem do repositório e descreve o RUNTIME das Cloud Functions — é por ele que o Firebase
 * escolhe em qual Node a function roda. Ele não descreve a máquina de quem instala, e é por isso que o
 * npm avisa `EBADENGINE` quando as duas versões diferem: o aviso é esperado e não impede nada. Trocar
 * o valor por uma faixa (`>=22`) calaria o aviso e passaria a deixar a escolha do runtime ambígua para
 * o Firebase — o preço errado pela linha de saída.
 */
export const packageFunctionsPackageJson = (
  source: RepoFunctionsPackage,
  version: string,
): string => JSON.stringify({
  name: FUNCTIONS_PACKAGE_NAME,
  version,
  private: true,
  main: 'index.js',
  /**
   * O `exports` está aqui por UMA razão, e ela não é organização: é ele que faz a auto-referência de
   * pacote funcionar. Sem ele, uma Cloud Function do escritório em `custom/` não tem como importar nada
   * da plataforma — não há `node_modules` que a contenha, e um caminho relativo dependeria de onde o
   * arquivo foi montado, que é justamente o que muda entre escrever e deployar.
   *
   * Com ele, `require('${FUNCTIONS_PACKAGE_NAME}/office')` resolve de dentro do próprio pacote. É por
   * isso que não há dependência nova nem alteração no `package-lock.json` que viaja ao lado.
   *
   * O `.` continua sendo o `index.js`: é ele que o Firebase carrega, e restringir os subcaminhos sem
   * declará-lo tiraria a plataforma do ar inteira.
   */
  exports: {
    '.': './index.js',
    [`./${OFFICE_SUBPATH}`]: {
      types: `./lib/${OFFICE_SUBPATH}/index.d.ts`,
      default: `./lib/${OFFICE_SUBPATH}/index.js`,
    },
  },
  engines: source.engines ?? { node: '22' },
  scripts: {
    build: 'tsc -p custom/tsconfig.json',
  },
  dependencies: source.dependencies ?? {},
  devDependencies: source.devDependencies ?? {},
}, null, 2) + '\n';

/**
 * Entrypoint da instalação. O espalhamento mantém os nomes PLANOS (`onUserCreated`, e não
 * `kernel-onUserCreated`), que é o que os deploys por nome e os gatilhos já existentes esperam.
 */
export const packageFunctionsIndexJs = (): string => `// Generated by "microteia pack". Do not edit.
//
// The deployed function set is the compiled kernel plus whatever this installation added under
// custom/. Kernel functions cannot be overridden here: custom/ is spread last, so a name collision
// would silently replace a kernel trigger — keep your function names distinct.
const kernel = require('./lib/index.js');
const custom = require('./custom/lib/index.js');

module.exports = { ...kernel, ...custom };
`;

/**
 * O `exclude` é cinto de segurança, não redundância: o `gatherCustomFunctions` já não copia teste para
 * cá, mas ele reconhece as duas convenções usuais (`*.test.ts`, `__tests__/`) e um arquivo fora delas
 * chegaria. Aqui ele chega e não compila — o que é um upload maior, e não um deploy quebrado.
 */
export const packageCustomTsconfig = (): string => JSON.stringify({
  compilerOptions: {
    module: 'commonjs',
    moduleResolution: 'node',
    /**
     * O `paths` só resolve TIPO; o `require` emitido continua sendo `microteia-functions/office`, e é o
     * `exports` do pacote que o resolve em execução. Os dois lados são necessários porque o
     * `moduleResolution: 'node'` é anterior ao `exports` e não o lê — e trocá-lo por `node16` mudaria,
     * de quebra, como TODO import do escritório resolve.
     *
     * Sem `baseUrl` de propósito: o `paths` relativo ao tsconfig basta desde o TypeScript 4.1, e um
     * `baseUrl` faria qualquer arquivo de `src/` virar um módulo de nome curto por acidente.
     */
    paths: { [OFFICE_MODULE]: [`../lib/${OFFICE_SUBPATH}/index.d.ts`] },
    target: 'es2022',
    lib: ['ES2022'],
    types: ['node'],
    rootDir: 'src',
    outDir: 'lib',
    strict: true,
    esModuleInterop: true,
    skipLibCheck: true,
    sourceMap: true,
    noImplicitReturns: true,
  },
  include: ['src'],
  exclude: ['**/*.test.ts', '**/*.test.tsx', '**/*.spec.ts', '**/*.spec.tsx', '**/__tests__/**'],
}, null, 2) + '\n';

export const packageCustomIndexTs = (): string => `// Cloud Functions belonging to this installation.
//
// Everything exported from this file is deployed alongside the Microteia kernel and survives a
// kernel upgrade — "microteia deploy" replaces lib/ but never touches custom/.
//
// Functions must be pinned to the same region as the rest of the installation, otherwise Firestore
// triggers will not fire. Example:
//
//   import { onCall } from 'firebase-functions/v2/https';
//
//   export const helloOffice = onCall({ region: 'southamerica-east1', cors: true }, () => {
//     return { ok: true };
//   });

export {};
`;

export const CONSOLE_PACKAGE_NAME = '@microteia/console';

/**
 * O Console empacotado para rodar FORA do repositório — e agora publicável.
 *
 * O `type: module` não é detalhe: o compilado é ESM, e sem esta declaração o Node só o carrega por
 * adivinhação de sintaxe — que existe a partir do 22.7 e falha em silêncio nas versões anteriores, com
 * "Cannot use import statement outside a module". O `bin` é o que dá o comando `microteia` global.
 *
 * Ele deixou de ser `private`, e isso resolve um ovo-e-galinha: enquanto o Console também tinha de ser
 * baixado de algum lugar, alguém precisava baixar o baixador — e o primeiro passo de quem instala era
 * uma pasta recebida por e-mail e um `ln -s` escrito à mão. Publicado, o registry já dá URL versionada,
 * impressão digital no lock, CDN e `npm outdated`, que era tudo o que o canal precisaria reimplementar.
 *
 * `files` é a lista exata, e o `CONSOLE-VERSIONS.md` está nela por um motivo que não é documentação: o
 * `unpack` lê aquele arquivo AO LADO do binário que está rodando para pô-lo na raiz da instalação. Fora
 * de `files`, ele não existe numa instalação global, e o comando passa a avisar que o Console não carrega
 * histórico — na máquina do escritório, e só lá.
 */
export const consolePackageJson = (version: string): string => JSON.stringify({
  name: CONSOLE_PACKAGE_NAME,
  version,
  description: 'Install and update Microteia in a Firebase project you own.',
  license: 'UNLICENSED',
  type: 'module',
  bin: { microteia: 'lib/index.js' },
  files: ['lib', 'README.md', 'CONSOLE-VERSIONS.md'],
  engines: { node: '>=22' },
  publishConfig: { access: 'public' },
}, null, 2) + '\n';

export const consoleReadme = (version: string): string => `# Microteia Console ${version}

Installs and updates Microteia in a Firebase project you own. It has no npm dependencies of its own —
what it needs are command-line tools that are already on the machine, listed at the bottom.

## Installing it

    npm i -g ${CONSOLE_PACKAGE_NAME}
    microteia --help

Or run it without installing anything:

    npx ${CONSOLE_PACKAGE_NAME} --help

Where npm's global prefix belongs to root — Node installed system-wide under \`/usr/local\` — the global
install fails with EACCES. Point npm at a prefix of your own instead of reaching for sudo, which would
write root-owned files that then need sudo to remove:

    npm config set prefix ~/.npm-global
    export PATH="$HOME/.npm-global/bin:$PATH"   # add to ~/.zshrc

This folder also runs as it is, with no npm at all:

    node lib/index.js --help

## Using it

    microteia init --name "<office>"
    microteia connect --project <your-firebase-project-id>
    microteia unpack --version latest
    microteia deploy

\`connect\` prints everything that has to be prepared in the Firebase project first — start with the
Blaze plan, since nothing else can be created without it.

\`unpack --version\` reads the published catalog, downloads the version and checks its sha256 before
touching what is installed. On a machine that cannot reach the catalog, name a file you already have:

    microteia unpack --kernel <microteia-kernel-x.y.z>.tgz

\`microteia --version\` answers what is installed here, and says so when a newer kernel is published.

Later, whenever an office installs an extension that needs server-side resources, run:

    microteia provision

The extension shows "Backend pending" in the application until you do, and stays out of the menu.

## What has to exist on this machine

| Tool          | Used for                                                       |
| ------------- | -------------------------------------------------------------- |
| Node.js 22+   | running this Console (newer is fine; the functions' own runtime is pinned to 22) |
| \`firebase\`    | every deploy — authenticate with \`firebase login\` first          |
| \`npm\`, \`tar\` | installing the functions' dependencies and unpacking the kernel  |
| \`gcloud\`      | creating the App Engine application, and reading which extensions an office installed (\`gcloud auth login\`) |

The \`pack\` and \`publish\` commands in here build and release the platform itself, and only work inside
the Microteia repository.

## What changed in this Console

\`CONSOLE-VERSIONS.md\`, in this folder. \`unpack\` copies it into the installation it manages, beside the
platform's own \`KERNEL-VERSIONS.md\` — each history travels with the artifact it describes.
`;

